using System.Collections.Frozen;
using System.Runtime.InteropServices;

namespace CatalogSvc;

/// <summary>
/// Builder that collects products, then produces an immutable
/// <see cref="ProductCatalog"/> backed by frozen dictionaries.
/// </summary>
public sealed class ProductCatalogBuilder
{
    private readonly Dictionary<string, string> _categories = new(StringComparer.OrdinalIgnoreCase);
    private readonly Dictionary<string, decimal> _prices = new(StringComparer.OrdinalIgnoreCase);

    public void AddProduct(string code, string category, decimal price)
    {
        _categories[code] = category;
        _prices[code] = price;
    }

    public ProductCatalog Build() => new(_categories, _prices);
}

/// <summary>
/// Read-optimized product catalog.  All lookups use <see cref="FrozenDictionary{TKey,TValue}"/>
/// for minimal per-lookup overhead, and category→products is pre-indexed so
/// <see cref="GetProductsByCategory"/> is O(1) instead of O(n).
/// </summary>
public sealed class ProductCatalog
{
    private readonly FrozenDictionary<string, string> _categories;
    private readonly FrozenDictionary<string, decimal> _prices;
    // Reverse index: category → product codes (pre-built at construction time)
    private readonly FrozenDictionary<string, string[]> _productsByCategory;

    internal ProductCatalog(
        Dictionary<string, string> categories,
        Dictionary<string, decimal> prices)
    {
        _categories = categories.ToFrozenDictionary(StringComparer.OrdinalIgnoreCase);
        _prices = prices.ToFrozenDictionary(StringComparer.OrdinalIgnoreCase);

        _productsByCategory = categories
            .GroupBy(kvp => kvp.Value, StringComparer.OrdinalIgnoreCase)
            .ToFrozenDictionary(
                g => g.Key,
                g => g.Select(kvp => kvp.Key).ToArray(),
                StringComparer.OrdinalIgnoreCase);
    }

    public string? GetCategory(string code)
        => _categories.TryGetValue(code, out var cat) ? cat : null;

    public decimal GetTotalPrice(ReadOnlySpan<string> codes)
    {
        decimal total = 0m;
        foreach (var code in codes)
        {
            if (_prices.TryGetValue(code, out var price))
                total += price;
        }
        return total;
    }

    /// <summary>
    /// O(1) category lookup via pre-built reverse index.
    /// Returns a read-only view; callers that need a mutable list can copy.
    /// </summary>
    public ReadOnlySpan<string> GetProductsByCategory(string category)
        => _productsByCategory.TryGetValue(category, out var products)
            ? products.AsSpan()
            : ReadOnlySpan<string>.Empty;
}

